import {readFile,writeFile} from 'node:fs/promises';
const names=['すべて','ろりは','めろな','ゆは','もか'];
const validHex=s=>typeof s==='string'&&/^#[0-9a-fA-F]{6}$/.test(s);
const original=await readFile('assets/config.js','utf8');
const gas=original.match(/gasUrl\s*:\s*['"]([^'"]+\/exec)['"]/i)?.[1];
if(!gas){console.log('Site A new GAS is not configured. Using the existing initial public palette.');process.exit(0);}
try{
 const url=new URL(gas);url.searchParams.set('action','public');url.searchParams.set('t',String(Date.now()));
 const response=await fetch(url,{redirect:'follow',signal:AbortSignal.timeout(25000)});
 if(!response.ok)throw Error('Public GAS response '+response.status);
 const payload=await response.json();
 if(payload.ok===false)throw Error('Public GAS returned an error');
 const source=payload?.data?.colors||payload?.colors;
 if(!source||typeof source!=='object')throw Error('No public colors');
 const colors={};
 for(const name of names){
  const v=source[name];
  const first=typeof v==='string'?v:v?.first,second=typeof v==='string'?v:(v?.second||first);
  if(!validHex(first)||!validHex(second))throw Error('Invalid palette for '+name);
  colors[name]={mode:v?.mode==='gradient'?'gradient':'solid',first:first.toLowerCase(),second:second.toLowerCase()};
 }
 await writeFile('assets/initial-colors.js','/* Public Site A colors, generated by GitHub Actions. */\nwindow.SITE_D_BOOTSTRAP_COLORS='+JSON.stringify({syncedAt:new Date().toISOString(),colors})+';\n');
 console.log('Synchronized '+names.length+' public Site A colors');
}catch(err){console.warn('Color sync unavailable, keeping previously published public colors: '+err.message);}
